// Explanation: Robin has a hidden trust score; apology raises it by 1, insult lowers it by 1, gift does nothing, and Robin is warm only if trust is positive.
function visible(actions) {
  let score = 0;
  for (const a of actions) {
    if (a === "insult") score -= 1;
    else if (a === "apologise") score += 1;
    // gift has no direct effect
  }
  return { mood: score > 0 ? "warm" : "cold" };
}

// Explanation: Robin is permanently cold if the first action is an insult or if there are ever two insults in a row; otherwise Robin is warm.
function visible(actions) {
  let doomed = false;
  let prev = null;
  for (const a of actions) {
    if (a === "insult" && (prev === null || prev === "insult")) {
      doomed = true;
    }
    prev = a;
  }
  return { mood: doomed ? "cold" : "warm" };
}

// Explanation: Robin tracks a hidden grudge; insults add grudge, apologies clear small grudges and warm Robin, gifts reduce grudge but do not by themselves warm Robin.
function visible(actions) {
  let mood = "cold";
  let grudge = 0;
  for (const a of actions) {
    if (a === "insult") {
      grudge += 1;
      mood = "cold";
    } else if (a === "apologise") {
      if (grudge <= 1) {
        grudge = 0;
        mood = "warm";
      } else {
        mood = "cold";
      }
    } else if (a === "gift") {
      if (grudge > 0) grudge -= 1;
      // gift only pays down grudge; it does not directly change mood
    }
  }
  return { mood };
}

// Explanation: Robin tracks unresolved insult debt and whether any apology has happened; both apology and gift reduce debt, but Robin is warm only with at least one apology and zero debt.
function visible(actions) {
  let debt = 0;
  let hasApology = false;
  for (const a of actions) {
    if (a === "insult") {
      debt += 1;
    } else if (a === "apologise") {
      hasApology = true;
      debt = Math.max(0, debt - 1);
    } else if (a === "gift") {
      debt = Math.max(0, debt - 1);
    }
  }
  return { mood: (hasApology && debt === 0) ? "warm" : "cold" };
}

