// Rival 1: hidden anger meter; insults add 1, apologies forgive a lone insult or chip away at anger, gifts only help when anger is at least 2.
function visible(actions) {
  let anger = 0;
  for (const action of actions) {
    if (action === "insult") {
      anger += 1;
    } else if (action === "apologise") {
      if (anger === 1) anger = 0;
      else if (anger > 0) anger -= 1;
    } else if (action === "gift") {
      if (anger >= 2) anger -= 1;
    }
  }
  return { mood: anger === 0 ? "warm" : "cold" };
}

// Rival 2: hidden debt; a gift arms the next apology to forgive all debt, otherwise apology pays down one unit of debt.
function visible(actions) {
  let debt = 0;
  let giftReady = false;
  for (const action of actions) {
    if (action === "insult") {
      debt += 1;
      giftReady = false;
    } else if (action === "gift") {
      giftReady = true;
    } else if (action === "apologise") {
      if (giftReady) {
        debt = 0;
        giftReady = false;
      } else if (debt > 0) {
        debt -= 1;
      }
    }
  }
  return { mood: debt === 0 ? "warm" : "cold" };
}

// Rival 3: hidden anger plus last action; consecutive insults sting more, and an apology immediately after a gift wipes anger clean.
function visible(actions) {
  let anger = 0;
  let last = null;
  for (const action of actions) {
    if (action === "insult") {
      anger += last === "insult" ? 2 : 1;
      last = "insult";
    } else if (action === "apologise") {
      if (last === "gift") {
        anger = 0;
      } else if (anger <= 1) {
        anger = 0;
      } else {
        anger -= 1;
      }
      last = "apologise";
    } else if (action === "gift") {
      last = "gift";
    }
  }
  return { mood: anger === 0 ? "warm" : "cold" };
}

// Rival 4: hidden grudge in units of 2; the first gift primes a combo, a second gift can reduce grudge, and an apology while primed clears everything.
function visible(actions) {
  let grudge = 0;
  let giftPrimed = false;
  for (const action of actions) {
    if (action === "insult") {
      grudge += 2;
      giftPrimed = false;
    } else if (action === "gift") {
      if (giftPrimed) {
        grudge = Math.max(0, grudge - 2);
      } else {
        giftPrimed = true;
      }
    } else if (action === "apologise") {
      if (giftPrimed) {
        grudge = 0;
        giftPrimed = false;
      } else {
        grudge = Math.max(0, grudge - 2);
      }
    }
  }
  return { mood: grudge === 0 ? "warm" : "cold" };
}

